const sourceFor=category=>category==='Layer masks'?sources.masks:category==='Free local MCP integration'?'https://modelcontextprotocol.io/docs/develop/build-server':category.includes('font library')?'https://developers.google.com/fonts/docs/developer_api':category.includes('Auto layout grid')?sources.grid:category.includes('Auto layout')||category.includes('Constraints')?sources.layout:category.includes('Layout guide')?sources.guides:category.includes('Draw')?sources.draw:category.includes('Dev Mode')?sources.dev:category.includes('Prototype')?sources.proto:category.includes('keyboard')?sources.keyboard:category.includes('plugin')||category.includes('Plugins')||category.includes('interchange')?sources.plugin:category.includes('Layer')||category.includes('Pages')?sources.sidebar:sources.overview;
let old=[];try{old=JSON.parse(fs.readFileSync('public/features.json','utf8'));}catch{}
const features=Object.entries(groups).flatMap(([category,items],g)=>items.split(';').map((name,i)=>{
 const previous=old.find(f=>f.category===category&&f.name===name.trim());
 return {id:`UI-${String(g+1).padStart(2,'0')}-${String(i+1).padStart(3,'0')}`,category,name:name.trim(),priority:category.includes('improvements')?'after-parity':'must',status:previous?.status??'planned',verification:previous?.verification??'reference-verification-pending',source:category.includes('improvements')?null:sourceFor(category),notes:previous?.notes??''};
}));
fs.mkdirSync('public',{recursive:true});fs.mkdirSync('docs',{recursive:true});
fs.writeFileSync('src/feature-meta.ts',`// Generated by scripts/inventory.mjs\nexport const FEATURE_COUNT = ${features.length};\nexport const APP_VERSION = ${JSON.stringify(JSON.parse(fs.readFileSync('package.json','utf8')).version)};\n`);
fs.writeFileSync('public/features.json',JSON.stringify(features,null,2)+'\n');
const counts=features.reduce((a,f)=>(a[f.status]=(a[f.status]||0)+1,a),{});
let md=`# Oanarina UI Tool — feature register\n\n${features.length} individually named requirements. ${features.filter(f=>f.priority==='must').length} required baseline items; ${features.filter(f=>f.priority==='after-parity').length} later Oanarina improvements.\n\nThis is a working parity specification, not a claim of completeness or of implemented Figma compatibility. Reference links identify category-level starting points; each requirement marked reference-verification-pending still needs an in-app or documentation check. Several OS integration, reliability, and cross-product requirements are Oanarina requirements rather than verified Figma functions. Figma Design is the first implementation target; Draw, Dev Mode, FigJam, Slides, Sites, Buzz and Make remain in scope in later phases. Features introduced by a future Figma update require another audit.\n\nStatus: ${JSON.stringify(counts)}. **planned** = not implemented; **partial** = material limits documented; **implemented** = working path with validation evidence. Production parity requires additional accessibility, performance, platform and user acceptance testing even for implemented items. No binary .fig import/export claim is made.\n\nMachine-readable source: public/features.json. Regenerate this document with npm run inventory.\n\n`;
for(const category of Object.keys(groups)){md+=`## ${category}\n\n| ID | Required behavior | Status | Verification / limits |\n| --- | --- | --- | --- |\n`;for(const f of features.filter(f=>f.category===category))md+=`| ${f.id} | ${f.name} | ${f.status} | ${f.notes||f.verification} |\n`;md+='\n';}
md+='## Reference starting points\n\n'+Object.entries(sources).map(([n,url])=>`- [${n}](${url})`).join('\n')+'\n';
fs.writeFileSync('docs/FEATURE-REGISTER.md',md);
console.log(JSON.stringify({total:features.length,required:features.filter(f=>f.priority==='must').length,groups:Object.keys(groups).length,status:counts},null,2));
